create table RB_LIMIT_CTRL_CONF (LIMIT_SCENE_NO VARCHAR(50) not null  ,LIMIT_BRANCH_ID VARCHAR(30) not null  ,LIMIT_BRANCH_RANGE VARCHAR(1) null  ,VALID_FLAG VARCHAR(1) null  ,SUM_TYPE VARCHAR(1) null  ,CTRL_ITEM_TYPE VARCHAR(1) null  ,PERIOD_TYPE VARCHAR(1) null  ,PERIOD_VALUE VARCHAR(5) null  ,LIMIT_CTRL_AMT DECIMAL(38,2) null  ,LIMIT_CTRL_NUM INT null  ,ALLOW_CUSTOM_FLAG VARCHAR(1) null  ,ALLOW_EXCEED_FLAG VARCHAR(1) null  ,LIMIT_CTRL_BGN_DATE TIMESTAMP(3) null  ,LIMIT_CTRL_END_DATE TIMESTAMP(3) null  ,LIMIT_CTRL_BGN_TIME VARCHAR(26) null  ,LIMIT_CTRL_END_TIME VARCHAR(26) null  ,DEAL_FLOW VARCHAR(1) null  ,ONLY_CUSTOM VARCHAR(1) null  ,TEMP_LIMIT_FLAG VARCHAR(1) null  ,TEMP_LIMIT_VALID_TERM VARCHAR(5) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  , primary key(LIMIT_SCENE_NO,LIMIT_BRANCH_ID));